<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {get,post,put,patch,del,message} from '../services/api.js';import {useAuth,useSaved,useUi} from '../stores/index.js';import {useRouter,useRoute} from 'vue-router';import RestaurantCard from '../components/restaurants/RestaurantCard.vue';import ConfirmDialog from '../components/ConfirmDialog.vue';import Icon from '../components/common/Icon.vue';import DashShell from '../components/layout/DashShell.vue';
const route=useRoute(),auth=useAuth(),saved=useSaved(),ui=useUi(),router=useRouter(),tab=ref('Profile'),favorites=ref([]),reviews=ref([]),notifications=ref([]),collections=ref([]),error=ref(''),name=ref(''),collectionName=ref(''),searchHistory=ref([]),loading=ref(true),busy=ref(''),touched=ref(false),confirming=ref(''),filter=ref('');
const tabs=['Profile','Favorites','Reviews','Collections','Notifications','Search history','Settings'];
const nameErr=computed(()=>touched.value&&name.value.trim().length<2?'Enter a display name of at least 2 characters.':'');
const collErr=computed(()=>touched.value&&!collectionName.value.trim()?'Give your collection a name.':'');
let loadVersion=0,disposed=false,refreshTimer;
const lastUpdated=ref(null),refreshing=ref(false);
async function load(){
 const version=++loadVersion;refreshing.value=true;error.value='';
 try{
  await auth.load();if(!auth.user){router.push('/login');return false;}
  const results=await Promise.all(['/me/favorites','/me/reviews','/notifications','/me/collections','/me/search-history'].map(url=>get(url,{_refresh:Date.now()})));
  if(disposed||version!==loadVersion)return false;
  [favorites.value,reviews.value,notifications.value,collections.value,searchHistory.value]=results.map(r=>r.data);
  saved.replaceRemote(favorites.value.map(r=>r._id));
  if(!name.value||name.value===previousName)name.value=auth.user.name;
  previousName=auth.user.name;lastUpdated.value=new Date();return true;
 }catch(e){if(!disposed&&version===loadVersion)error.value=message(e);return false;}
 finally{if(!disposed&&version===loadVersion){loading.value=false;refreshing.value=false;}}
}
let previousName='';
function autoRefresh(){if(document.hidden||refreshing.value||busy.value||confirming.value||name.value!==previousName||collectionName.value||document.activeElement?.matches('input,textarea,select'))return;load();}
function fromPath(){tab.value={'/account/favorites':'Favorites','/account/reviews':'Reviews','/account/collections':'Collections','/account/notifications':'Notifications','/account/search-history':'Search history','/account/settings':'Settings'}[route.path]||'Profile';touched.value=false;filter.value='';}
function choose(x){const paths={Profile:'/account',Favorites:'/account/favorites',Reviews:'/account/reviews',Collections:'/account/collections',Notifications:'/account/notifications','Search history':'/account/search-history',Settings:'/account/settings'};router.push(paths[x]);}
onMounted(()=>{fromPath();load();refreshTimer=setInterval(autoRefresh,15000);window.addEventListener('focus',autoRefresh);window.addEventListener('saved-changed',load);document.addEventListener('visibilitychange',autoRefresh);});onUnmounted(()=>{disposed=true;++loadVersion;clearInterval(refreshTimer);window.removeEventListener('focus',autoRefresh);window.removeEventListener('saved-changed',load);document.removeEventListener('visibilitychange',autoRefresh);});watch(()=>route.path,()=>{fromPath();load();});
async function action(fn,key='',msg='Saved.'){if(busy.value)return false;busy.value=key||'action';try{await fn();ui.toast(msg);await load();return true;}catch(e){ui.toast(message(e),'error');return false;}finally{busy.value='';}}
async function save(){touched.value=true;if(nameErr.value){document.getElementById('account-name')?.focus();return;}await action(async()=>{auth.user=(await patch('/me',{name:name.value.trim()})).data;},'name','Display name saved.');touched.value=false;}
async function download(){busy.value='download';try{const data=(await get('/me/data')).data;const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='bonappefind-my-data.json';a.click();URL.revokeObjectURL(url);ui.toast('Your data download has started.');}catch(e){ui.toast(message(e),'error');}finally{busy.value='';}}
async function remove(){busy.value='delete';try{await del('/me');localStorage.removeItem('bonappefind_token');auth.user=null;confirming.value='';router.push('/');ui.toast('Account deleted.');}catch(e){ui.toast(message(e),'error');}finally{busy.value='';}}
async function addCollection(){touched.value=true;if(collErr.value){document.getElementById('collection-name')?.focus();return;}if(!saved.saved.length){ui.toast('Save a few restaurants first, then create a collection from them.','error');return;}if(await action(()=>post('/me/collections',{name:collectionName.value.trim(),restaurants:saved.saved,isPublic:false}),'collection','Collection created.')){collectionName.value='';touched.value=false;}}
const shownHistory=computed(()=>searchHistory.value.filter(h=>!filter.value||h.query.toLowerCase().includes(filter.value.toLowerCase())));
const tabIcons={Profile:'user',Favorites:'heart',Reviews:'star',Collections:'book',Notifications:'calendar','Search history':'search',Settings:'sliders'};
const navItems=computed(()=>tabs.map(label=>({label,icon:tabIcons[label],badge:label==='Notifications'?(notifications.value.filter(n=>!n.isRead).length||''):''})));
const stripStats=computed(()=>[{label:'Saved restaurants',value:favorites.value.length},{label:'Reviews written',value:reviews.value.length},{label:'Collections',value:collections.value.length},{label:'Unread notifications',value:notifications.value.filter(n=>!n.isRead).length}]);
const profileStats=computed(()=>[{label:'Saved',value:favorites.value.length},{label:'Reviews',value:reviews.value.length},{label:'Lists',value:collections.value.length}]);
async function logout(){await auth.logout();router.push('/logged-out');}
</script>
<template>
<DashShell title="Customer dashboard" subtitle="Your saved restaurants, reviews and lists in one place." :nav="navItems" :active="tab" :stats="stripStats" :profile-stats="profileStats" role-label="Customer" @select="choose" @logout="logout">
  <template #actions><RouterLink to="/restaurants" class="btn d-primary"><Icon name="search" :size="16"/>Browse restaurants</RouterLink></template>
  <template #profile-links><RouterLink v-if="auth.user?.role==='owner'" to="/owner" class="btn d-primary">Open owner dashboard</RouterLink><RouterLink to="/account/favorites" class="btn d-primary"><Icon name="heart" :size="16"/>Saved list</RouterLink></template>
  <div class="row" style="margin:16px 0"><button type="button" class="secondary" :disabled="refreshing||!!busy" @click="load()">{{refreshing?'Refreshing…':'Refresh dashboard'}}</button><span v-if="lastUpdated" class="small muted" role="status">Updated {{lastUpdated.toLocaleTimeString()}}</span></div>
  <p v-if="error" class="error-box" role="alert">{{error}}</p>
  <div class="tabs" role="tablist" aria-label="Account sections"><button v-for="x in tabs" :key="x" role="tab" class="secondary toggle" :class="{active:tab===x}" :aria-selected="tab===x" :tabindex="tab===x?0:-1" @click="choose(x)">{{x}}<span v-if="x==='Notifications'&&notifications.some(n=>!n.isRead)" class="count-pill">{{notifications.filter(n=>!n.isRead).length}}</span></button></div>
  <Transition name="tab" mode="out-in"><div :key="tab" class="tab-panel" role="tabpanel">
    <div v-if="loading" class="skeleton" aria-busy="true"></div>
    <section v-else-if="tab==='Profile'" class="split profile-split">
      <div class="card pad stack"><h2>Hello, {{auth.user?.name}}</h2>
        <dl class="facts"><div><dt>Account ID</dt><dd>{{auth.user?.account_id}}</dd></div><div><dt>Email</dt><dd>{{auth.user?.email}}</dd></div><div><dt>Email verification</dt><dd><span class="badge" :class="auth.user?.emailVerified?'A':''">{{auth.user?.emailVerified?'Verified':'Pending'}}</span></dd></div></dl>
        <RouterLink v-if="!auth.user?.emailVerified" to="/verify-email" class="btn secondary">Verify your email. Tap here to verify your email address.</RouterLink><RouterLink v-if="auth.user?.role==='customer'" to="/account/suggestions" class="btn secondary">Your restaurant suggestions</RouterLink><RouterLink v-if="auth.user?.role==='customer'" to="/suggest-restaurant" class="btn secondary">Suggest a Restaurant</RouterLink>
        <form class="stack" novalidate @submit.prevent="save"><div class="field"><label for="account-name">Display name</label><input id="account-name" v-model="name" :aria-invalid="!!nameErr" aria-describedby="account-name-msg" @blur="touched=true"><p id="account-name-msg" v-if="nameErr" class="field-msg">{{nameErr}}</p></div><button :class="{'is-loading':busy==='name'}" :disabled="!!busy||name===auth.user?.name"><span>Save name</span></button></form>
      </div>
      <aside class="card pad stack"><h2>Quick links</h2><RouterLink class="btn secondary" to="/restaurants"><Icon name="search" :size="18"/>Browse restaurants</RouterLink><RouterLink class="btn secondary" to="/account/favorites"><Icon name="heart" :size="18"/>Manage saved list</RouterLink><RouterLink v-if="auth.user?.role==='owner'" class="btn" to="/owner">Open owner dashboard <Icon name="arrow-right" :size="16"/></RouterLink></aside>
    </section>
    <div v-else-if="tab==='Favorites'"><div v-if="favorites.length" class="grid stagger"><RestaurantCard v-for="(r,i) in favorites" :key="r._id" :restaurant="r" :style="{'--i':i%9}"/></div><div v-else class="card empty-results"><span class="empty-icon"><Icon name="heart" :size="28"/></span><h2>No saved restaurants yet</h2><p class="muted">Tap the heart on any restaurant to keep it here.</p><div class="row"><RouterLink to="/restaurants" class="btn cta">Browse restaurants</RouterLink></div></div></div>
    <section v-else-if="tab==='Reviews'" class="stack"><article v-for="r in reviews" :key="r._id" class="card pad"><p class="stars-line"><span aria-hidden="true">{{'★'.repeat(r.rating)}}</span><span class="sr-only">{{r.rating}} stars</span> · <b>{{r.title}}</b> <span class="badge">{{r.status}}</span></p><p>{{r.comment}}</p><RouterLink :to="'/restaurants/'+r.restaurant" class="link-arrow">View restaurant and edit review <Icon name="arrow-right" :size="16"/></RouterLink></article><div v-if="!reviews.length" class="card empty-results"><h2>No reviews yet</h2><p class="muted">Share a meal on any restaurant page.</p></div></section>
    <section v-else-if="tab==='Collections'" class="stack"><form class="card pad collection-form" novalidate @submit.prevent="addCollection"><div class="field"><label for="collection-name">New collection name</label><input id="collection-name" v-model="collectionName" placeholder="e.g. Date-night spots" :aria-invalid="!!collErr" aria-describedby="collection-name-msg" @blur="touched=true"><p id="collection-name-msg" v-if="collErr" class="field-msg">{{collErr}}</p><p v-else class="field-msg hint">Built from your {{saved.saved.length}} saved {{saved.saved.length===1?'restaurant':'restaurants'}}.</p></div><button :class="{'is-loading':busy==='collection'}" :disabled="!!busy"><span>Create collection</span></button></form><article v-for="c in collections" :key="c._id" class="card pad"><h2>{{c.name}}</h2><p>{{c.restaurants.length}} restaurants · <span class="badge">{{c.isPublic?'Public':'Private'}}</span></p><div class="row"><button class="secondary" :disabled="!!busy" @click="action(()=>put('/me/collections/'+c._id,{...c,isPublic:!c.isPublic}),'c'+c._id,c.isPublic?'Collection is now private.':'Collection is now public.')">{{c.isPublic?'Make private':'Make public'}}</button><RouterLink v-if="c.isPublic" :to="'/collections/'+c._id" class="btn secondary">Open shareable collection</RouterLink><button class="secondary" :disabled="!!busy" @click="action(()=>del('/me/collections/'+c._id),'d'+c._id,'Collection deleted.')">Delete</button></div></article><div v-if="!collections.length" class="card empty-results"><h2>No collections yet</h2><p class="muted">Name a collection above to group your saved restaurants.</p></div></section>
    <section v-else-if="tab==='Notifications'" class="stack"><article v-for="n in notifications" :key="n._id" class="card pad note" :class="{unread:!n.isRead}"><div class="row between"><b>{{n.title}}</b><span v-if="!n.isRead" class="badge">New</span><span v-else class="small muted">Read</span></div><p>{{n.message}}</p><div class="row"><RouterLink :to="n.link||'/account'" class="link-arrow">Open <Icon name="arrow-right" :size="16"/></RouterLink><button v-if="!n.isRead" class="secondary small" :disabled="!!busy" @click="action(()=>patch('/notifications/'+n._id+'/read'),'n'+n._id,'Marked as read.')">Mark read</button></div></article><div v-if="!notifications.length" class="card empty-results"><h2>You are all caught up</h2><p class="muted">New notifications will appear here.</p></div></section>
    <section v-else-if="tab==='Search history'" class="stack"><div class="toolbar"><div class="search-wrap"><label class="sr-only" for="history-filter">Filter search history</label><input id="history-filter" v-model="filter" type="search" placeholder="Filter your searches"><button v-if="filter" type="button" class="clear-x" aria-label="Clear filter" @click="filter=''"><Icon name="x" :size="16"/></button></div><button class="secondary" :disabled="!searchHistory.length||!!busy" @click="confirming='history'">Clear search history</button></div><RouterLink v-for="h in shownHistory" :key="h._id" :to="{path:'/restaurants',query:h.filters}" class="card pad history-item"><span><Icon name="search" :size="16"/> {{h.query}}</span><span class="small muted">{{h.createdAt?.slice(0,10)}}</span></RouterLink><div v-if="!shownHistory.length" class="card empty-results"><h2>{{searchHistory.length?'No searches match':'No search history'}}</h2><p class="muted">{{searchHistory.length?'Try another word.':'Your recent searches will show up here.'}}</p></div></section>
    <section v-else class="card pad stack reading"><h2>Privacy and preferences</h2><label class="check"><input :checked="auth.user?.preferences?.emailAlerts" type="checkbox" @change="action(()=>patch('/me',{preferences:{emailAlerts:$event.target.checked}}),'pref','Preference saved.')"> Email alerts preference</label><p class="small muted">SMTP must be configured for transactional email delivery. Scheduled newsletters are not sent by this starter.</p><div class="row"><button class="secondary" :class="{'is-loading':busy==='download'}" :disabled="!!busy" @click="download"><span>Download my data</span></button><button class="cta" :disabled="!!busy" @click="confirming='account'">Delete my account</button></div></section>
  </div></Transition>
  <ConfirmDialog v-if="confirming==='account'" title="Delete your account?" text="This permanently removes your account, your reviews and your saved lists. This cannot be undone." confirm-label="Delete account" :busy="busy==='delete'" @cancel="confirming=''" @confirm="remove"/>
  <ConfirmDialog v-if="confirming==='history'" title="Clear search history?" text="Your recent searches will be removed from your account." confirm-label="Clear history" @cancel="confirming=''" @confirm="action(()=>del('/me/search-history'),'history','Search history cleared.');confirming=''"/>
</DashShell>
</template>
<style scoped>.facts{display:grid;gap:14px;margin:0}.facts>div{display:grid;grid-template-columns:150px 1fr;gap:12px;align-items:center;padding-bottom:14px;border-bottom:1px solid var(--color-border)}.facts dt{margin:0;color:var(--color-muted);font-size:14px;font-weight:700}.facts dd{margin:0;overflow-wrap:anywhere}.profile-split{grid-template-columns:minmax(0,1.6fr) minmax(0,1fr)}.collection-form{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:18px;align-items:start}.collection-form .field{margin:0}.collection-form button{margin-top:28px}.history-item{display:flex;justify-content:space-between;gap:16px;align-items:center;text-decoration:none;padding:18px 24px}.note.unread{border-left:5px solid var(--moss-gardens)}.check{display:flex;align-items:center;gap:10px;font-weight:700}.stars-line{color:var(--star);margin-bottom:8px}.stars-line b,.stars-line .badge{color:var(--color-text)}@media(max-width:900px){.profile-split{grid-template-columns:1fr}}@media(max-width:600px){.facts>div{grid-template-columns:1fr;gap:4px}.collection-form{grid-template-columns:1fr}.collection-form button{margin-top:0}}</style>
